    static bool Selectable(PendingFile file){return file.Status=="Pending"||file.Status=="Error"||file.Status=="Review";}
    IList<string> SelectedIds(){return owner.State.Pending.Where(p=>selected.Contains(p.Id)&&Selectable(p)).Select(p=>p.Id).ToList();}
    void SizeCards(){if(sizing)return;sizing=true;try{int total=Math.Max(0,cards.Count*116-12);Control viewport=papers.Parent;if(viewport==null)return;paperScroll.Visible=total>viewport.ClientSize.Height;paperScroll.SetBounds(viewport.ClientSize.Width-18,0,18,viewport.ClientSize.Height);papers.SetBounds(0,0,Math.Max(1,viewport.ClientSize.Width-(paperScroll.Visible?22:0)),viewport.ClientSize.Height);paperScroll.LargeChange=Math.Max(1,papers.ClientSize.Height);paperScroll.Maximum=Math.Max(0,total-1);int limit=Math.Max(0,total-papers.ClientSize.Height);if(paperScroll.Value>limit)paperScroll.Value=limit;int width=Math.Max(100,papers.ClientSize.Width-14);int top=-paperScroll.Value;foreach(PendingFile file in owner.State.Pending){FileCard card;if(cards.TryGetValue(file.Id,out card)){card.SetBounds(0,top,width,104);top+=116;}}}finally{sizing=false;}}
    void ScrollPapers(int delta){if(!paperScroll.Visible)return;int max=Math.Max(0,paperScroll.Maximum-paperScroll.LargeChange+1);paperScroll.Value=Math.Max(0,Math.Min(max,paperScroll.Value-delta/120*114));}

    void HandleWheel(MouseEventArgs e){ScrollPapers(e.Delta);HandledMouseEventArgs handled=e as HandledMouseEventArgs;if(handled!=null)handled.Handled=true;}
    void ToggleSelection(){bool all=owner.State.Pending.Where(Selectable).All(p=>selected.Contains(p.Id));foreach(PendingFile file in owner.State.Pending.Where(Selectable)){if(all)selected.Remove(file.Id);else selected.Add(file.Id);}Render();}
    void UpdateButtons(){int n=SelectedIds().Count;analyze.Enabled=n>0&&!owner.IsAnalyzing;review.Enabled=owner.State.Pending.Any(p=>selected.Contains(p.Id)&&p.Analysis!=null&&Selectable(p));ignore.Enabled=n>0;selection.Text=n>0?"已选 "+n.ToString()+" 篇":"选择要处理的论文";analyze.Text=owner.IsAnalyzing?"正在分析…":n>0?"API 分析所选 · "+n.ToString():"API 分析所选";}
    public void Render() {
      if(IsDisposed)return;rendering=true;papers.SuspendLayout();
      try {
        bool connected=owner.ConnectionText.Contains("已连接");connection.Text=connected?"●  已连接":"●  等待连接";connection.ForeColor=connected?Color.FromArgb(29,137,96):Color.FromArgb(170,117,50);tips.SetToolTip(connection,owner.ConnectionText);folder.Text="下载目录\r\n"+(Path.GetFileName(owner.State.Folder.TrimEnd('\\','/')));tips.SetToolTip(folder,owner.State.Folder);
        try{AiConfiguration config=new AiSettingsStore(owner.Store).Load();ProviderPreset provider=ProviderPreset.All.FirstOrDefault(p=>p.Id==config.Selected);model.Text=string.IsNullOrWhiteSpace(config.Current.Model)?"先设置 API 与模型":provider==null?config.Current.Model:provider.Name;}catch{model.Text="API 设置需要检查";}
        count.Text=owner.State.Pending.Count.ToString()+" 篇待处理";first.ForeColor=owner.IsAnalyzing?Design.Blue:Design.Muted;second.ForeColor=owner.State.Pending.Any(p=>p.Status=="Review")?Color.FromArgb(29,137,96):Design.Muted;third.ForeColor=owner.State.Pending.Any(p=>p.Status=="Approved"||p.Status=="Importing")?Design.Blue:Design.Muted;
        HashSet<string> current=new HashSet<string>(owner.State.Pending.Select(p=>p.Id));foreach(string id in cards.Keys.Where(k=>!current.Contains(k)).ToList()){FileCard old=cards[id];papers.Controls.Remove(old);old.Dispose();cards.Remove(id);selected.Remove(id);}
        foreach(PendingFile file in owner.State.Pending){if(seen.Add(file.Id)&&Selectable(file))selected.Add(file.Id);FileCard card;if(!cards.TryGetValue(file.Id,out card)){card=new FileCard(file);FileCard captured=card;card.MouseWheel+=(s,e)=>HandleWheel(e);card.GotFocus+=(s,e)=>{int index=owner.State.Pending.FindIndex(p=>p.Id==captured.File.Id);int top=index*116;int max=Math.Max(0,paperScroll.Maximum-paperScroll.LargeChange+1);if(top<paperScroll.Value)paperScroll.Value=Math.Min(max,Math.Max(0,top));else if(top+104>paperScroll.Value+papers.Height)paperScroll.Value=Math.Min(max,Math.Max(0,top+104-papers.Height));};card.CheckedChanged+=(s,e)=>{if(rendering)return;if(!Selectable(captured.File)){captured.Checked=false;return;}if(captured.Checked)selected.Add(captured.File.Id);else selected.Remove(captured.File.Id);UpdateButtons();};card.DoubleClick+=(s,e)=>{if(captured.File.Analysis!=null)owner.Review(new[]{captured.File.Id});};tips.SetToolTip(card,file.Path);cards[file.Id]=card;papers.Controls.Add(card);}card.File=file;card.Checked=selected.Contains(file.Id)&&Selectable(file);card.Enabled=file.Status!="Analyzing";card.Invalidate();}
        empty.Visible=cards.Count==0;papers.Visible=cards.Count!=0;SizeCards();UpdateButtons();
      }finally{papers.ResumeLayout();rendering=false;}
    }
    void ShowApi(){using(ApiSettingsForm dialog=new ApiSettingsForm(owner.Store))dialog.ShowDialog(this);Render();}
    void ShowHistory(){using(HistoryForm dialog=new HistoryForm(owner.State))dialog.ShowDialog(this);}
    void ShowHelp(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"使用说明.txt");if(File.Exists(path))Process.Start(new ProcessStartInfo(path){UseShellExecute=true});else MessageBox.Show(this,"在 Zotero：工具 → 插件 → 从文件安装，选择随程序提供的连接插件 .xpi。","使用说明");}
    protected override void Dispose(bool disposing){if(disposing)tips.Dispose();base.Dispose(disposing);}
